# ruff: noqa: E501
"""Markdown report for the SA2.2 / SA2.3 baselines (Spanish prose, tables generated by code)."""

import datetime as dt
from dataclasses import dataclass

import numpy as np
import pandas as pd

from firecal.stages.grid.filters import FilterConfig
from firecal.stages.harmonize.evaluate import (
    INTERVALS,
    MAIN_PAIRS,
    METHODS,
    NOMINAL,
    PAIRS,
    FoldOut,
    coverage_table,
    score_table,
)
from firecal.stages.harmonize.regions import Cube
from firecal.stages.harmonize.stability import step_summary

DIRECTION = {
    "viirs_to_modis": "VIIRS (S-NPP) -> MODIS-equivalente",
    "modis_to_viirs": "MODIS -> VIIRS-equivalente (serie inversa)",
}
STEP_GROUPS = {
    "2012-2017": (2012, 2017),
    "2018": (2018, 2018),
    "2019-2022": (2019, 2022),
    "2023": (2023, 2023),
    "2024-2025": (2024, 2025),
}


@dataclass
class ReportInput:
    cube: Cube
    folds: dict[tuple[str, str], list[FoldOut]]  # (pair, scheme) -> folds
    factors: pd.DataFrame
    grid_tables: dict[str, pd.DataFrame]
    det_tables: dict[str, pd.DataFrame]
    cfg: FilterConfig
    run_date: dt.date


def md_table(headers: list[str], rows: list[list]) -> list[str]:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return out


def pct(x: float, sign: bool = False) -> str:
    if x is None or not np.isfinite(x):
        return "-"
    return f"{x * 100:+.1f} %" if sign else f"{x * 100:.1f} %"


def num(x: float, nd: int = 3) -> str:
    return "-" if x is None or not np.isfinite(x) else f"{x:.{nd}f}"


def hhmm(h: float) -> str:
    if h is None or not np.isfinite(h):
        return "-"
    m = round((h % 24) * 60)
    return f"{m // 60 % 24:02d}:{m % 60:02d}"


def _row(scores: pd.DataFrame, pair, scheme, method, year, level) -> pd.Series | None:
    s = scores[
        (scores["pair"] == pair)
        & (scores["scheme"] == scheme)
        & (scores["method"] == method)
        & (scores["test_year"].astype(str) == str(year))
        & (scores["level"] == level)
    ]
    return s.iloc[0] if len(s) else None


def _lower(scores, pair, scheme, level="block-month", year="all") -> str:
    a, b = _row(scores, pair, scheme, "sf", year, level), _row(scores, pair, scheme, "qm", year, level)
    if a is None or b is None:
        return "-"
    return METHODS["sf"] if a["wape"] <= b["wape"] else METHODS["qm"]


def _all_folds(inp: ReportInput) -> list[FoldOut]:
    return [f for fs in inp.folds.values() for f in fs]


def build_report(inp: ReportInput) -> str:
    cube, cfg = inp.cube, inp.cfg
    folds = _all_folds(inp)
    scores = score_table(folds)
    cov = coverage_table(folds)
    snpp_first = cube.dates[cube.valid["snpp"]][0].strftime("%Y-%m")
    last = cube.dates[-1].strftime("%Y-%m")
    L: list[str] = ["# SA2.2 y SA2.3 Baselines de armonización MODIS-VIIRS", ""]
    L += [
        f"Corrida: {inp.run_date.isoformat()}, con `firecal harmonize evaluate` (tablas generadas por código). "
        "Fuente: archivos por país (Argentina) de NASA FIRMS, procesamiento standard "
        "(MODIS, VIIRS S-NPP y NOAA-20; el detalle de cada versión de procesamiento está sin verificar).",
        f"Período de los datos locales: 2000-11 a {last}; período de solapamiento usado: {snpp_first} a {last}.",
        f"Filtros: type en {list(cfg.types)}, confianza MODIS >= {cfg.modis_min_confidence}, "
        f"clase VIIRS en {list(cfg.viirs_classes)} (`FilterConfig` por defecto). Conteo: detecciones tras el "
        "filtro, sumadas desde la grilla de 0,1°.",
        "",
        "Todo es retrospectivo: cuenta focos ya detectados y no es un sistema de alerta.",
        "",
    ]

    # --- Resumen ---
    L += ["## Resumen", ""]
    nf = inp.factors.set_index("pair")
    L.append(
        f"- Factor nacional (cociente de sumas, en la muestra, {snpp_first} a {last}): "
        f"VIIRS -> MODIS = {num(nf.loc['viirs_to_modis', 'factor'])} "
        f"(día {num(nf.loc['viirs_to_modis', 'factor_day'])}, noche {num(nf.loc['viirs_to_modis', 'factor_night'])}); "
        f"MODIS -> VIIRS = {num(nf.loc['modis_to_viirs', 'factor'])} "
        f"(día {num(nf.loc['modis_to_viirs', 'factor_day'])}, noche {num(nf.loc['modis_to_viirs', 'factor_night'])})."
    )
    for pair in MAIN_PAIRS:
        for scheme, name in (("loyo", "año afuera"), ("rolling", "origen móvil")):
            a = _row(scores, pair, scheme, "sf", "all", "block-month")
            b = _row(scores, pair, scheme, "qm", "all", "block-month")
            ay = _row(scores, pair, scheme, "sf", "all", "block-year")
            by = _row(scores, pair, scheme, "qm", "all", "block-year")
            if a is None or b is None:
                continue
            L.append(
                f"- {DIRECTION[pair]}, {name}: WAPE bloque-mes SA2.2 {pct(a['wape'])} vs SA2.3 {pct(b['wape'])} "
                f"(menor error: {_lower(scores, pair, scheme)}); WAPE bloque-año SA2.2 {pct(ay['wape'])} vs "
                f"SA2.3 {pct(by['wape'])} (menor error: {_lower(scores, pair, scheme, 'block-year')}); "
                f"sesgo relativo SA2.2 {pct(a['bias'], True)}, SA2.3 {pct(b['bias'], True)}."
            )
    c = cov[
        (cov["pair"] == "modis_to_viirs")
        & (cov["scheme"] == "loyo")
        & (cov["test_year"].astype(str) == "all")
    ]
    for _, r in c.iterrows():
        L.append(
            f"- Serie inversa, cobertura empírica del intervalo {INTERVALS[r['interval']]} (nominal "
            f"{NOMINAL:.0%}, año afuera, bloque-mes con actividad): {pct(r['coverage'])}."
        )
    mod = inp.grid_tables["modis_snpp"]
    steps = step_summary(mod, "ratio", STEP_GROUPS)
    L.append(
        "- Cociente MODIS/S-NPP nacional por período (media de los cocientes anuales): "
        + ", ".join(f"{k} {num(v)}" for k, v in steps.items())
        + "."
    )
    types = inp.det_tables["types"]
    if not types.empty:
        ts = step_summary(types, "ratio_all", STEP_GROUPS)
        td = step_summary(types, "ratio_def", STEP_GROUPS)
        L.append(
            "- Mismo cociente sin filtro de `type`: "
            + ", ".join(f"{k} {num(v)}" for k, v in ts.items())
            + "; con el filtro por defecto desde las detecciones: "
            + ", ".join(f"{k} {num(v)}" for k, v in td.items())
            + "."
        )
    L.append("")

    # --- Datos y supuestos ---
    L += ["## Datos y supuestos", ""]
    L += [
        "- Escalas: MODIS = Terra + Aqua; VIIRS = S-NPP solo. NOAA-20 no se suma a S-NPP: se ajusta un factor "
        "de transferencia NOAA-20 -> S-NPP desde 2018-05.",
        "- Regiones: bloques de 2,5° (origen -90/-180), "
        f"{len(cube.blocks)} bloques con algún foco. Día y noche se ajustan por separado y se suman.",
        "- Meses parciales excluidos: S-NPP 2012-01, NOAA-20 2018-04, Aqua 2002-07.",
        f"- Primer mes de S-NPP en los datos locales: {snpp_first}.",
        "- Unidad: se ajusta sobre sumas por bloque x mes del año x día/noche; se evalúa por bloque-mes de cada "
        "año de test y por total bloque-año.",
        "- Año afuera: cada año es test una vez; el entrenamiento excluye el año de test y 6 meses a cada lado. "
        "Origen móvil: entrenar con todos los años anteriores, evaluar el siguiente (sin separación).",
        "- SA2.2: `f = (M + k * f_nacional) / (V + k)`; `k` se elige dentro del entrenamiento con año afuera "
        "interno (6 meses de separación), minimizando el WAPE bloque-mes, sobre la grilla "
        "{0, 5, 20, 100, 500, 2000, 10000}.",
        "- SA2.3: ajuste de cuantiles por bloque sobre totales bloque-mes (meses del año juntos); solo positivos; "
        "cero va a cero; sobre el máximo de entrenamiento, cociente constante; con menos de 12 meses positivos "
        "en alguna de las dos series el bloque usa el ajuste de todos los bloques juntos.",
        "- Métricas: sesgo relativo = suma(pred)/suma(obs) - 1; WAPE = suma|pred-obs|/suma(obs); MAE; devianza de "
        "Poisson media (media predicha mínima 0,001). Son totales de bloque-mes (n = bloques x meses de test) y "
        "totales bloque-año.",
        "",
    ]

    # --- Factores nacionales ---
    L += ["## Factores nacionales (en la muestra)", ""]
    L += [
        "Cociente de sumas objetivo/origen sobre todos los meses del par, sin validación (descriptivo). "
        "`NOAA-20 -> S-NPP` es el factor de transferencia desde 2018-05.",
        "",
    ]
    rows = [
        [
            PAIRS[r["pair"]].label,
            f"{r['from']} a {r['to']}",
            r["months"],
            num(r["factor"]),
            num(r["factor_day"]),
            num(r["factor_night"]),
        ]
        for _, r in inp.factors.iterrows()
    ]
    L += md_table(["Par", "Meses", "N", "Total", "Día", "Noche"], rows)
    L += ["", "Factor nacional por mes del año (día y noche juntos):", ""]
    mcols = [f"m{m:02d}" for m in range(1, 13)]
    rows = [
        [PAIRS[r["pair"]].label] + [num(r[c]) for c in mcols]
        for _, r in inp.factors.iterrows()
        if r["pair"] in MAIN_PAIRS
    ]
    L += md_table(["Par"] + [str(m) for m in range(1, 13)], rows)
    L.append("")

    # --- Errores ---
    L += ["## Error por método y sentido (todos los años de test juntos)", ""]
    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        rows = []
        for scheme, sname in (("loyo", "año afuera"), ("rolling", "origen móvil")):
            for method, mname in METHODS.items():
                a = _row(scores, pair, scheme, method, "all", "block-month")
                b = _row(scores, pair, scheme, method, "all", "block-year")
                if a is None:
                    continue
                rows.append(
                    [
                        sname,
                        mname,
                        pct(a["bias"], True),
                        pct(a["wape"]),
                        num(a["mae"], 1),
                        num(a["deviance"], 2),
                        pct(b["bias"], True),
                        pct(b["wape"]),
                        num(b["mae"], 1),
                    ]
                )
        L += md_table(
            [
                "Esquema",
                "Método",
                "Sesgo b-mes",
                "WAPE b-mes",
                "MAE b-mes",
                "Devianza b-mes",
                "Sesgo b-año",
                "WAPE b-año",
                "MAE b-año",
            ],
            rows,
        )
        L.append("")

    # --- Por año ---
    L += ["## Error por año de test (año afuera)", ""]
    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        years = sorted(
            {
                int(y)
                for y in scores[(scores["pair"] == pair) & (scores["scheme"] == "loyo")]["test_year"]
                if y != "all"
            }
        )
        rows = []
        for y in years:
            cells: list = [y]
            for method in METHODS:
                a = _row(scores, pair, "loyo", method, y, "block-month")
                b = _row(scores, pair, "loyo", method, y, "block-year")
                cells += [pct(a["bias"], True), pct(a["wape"]), pct(b["wape"])]
            cells.append(_lower(scores, pair, "loyo", "block-month", y))
            rows.append(cells)
        L += md_table(
            [
                "Año",
                "SA2.2 sesgo",
                "SA2.2 WAPE b-mes",
                "SA2.2 WAPE b-año",
                "SA2.3 sesgo",
                "SA2.3 WAPE b-mes",
                "SA2.3 WAPE b-año",
                "Menor error (b-mes)",
            ],
            rows,
        )
        L.append("")
    L += ["Detalle por bloque (año afuera, años de test juntos): `baselines_by_block.csv`.", ""]

    # --- k ---
    L += ["## Elección de k (SA2.2, año afuera)", ""]
    ks: dict[str, dict[int, str]] = {}
    for pair in MAIN_PAIRS:
        for f in inp.folds.get((pair, "loyo"), []):
            if f.method == "sf":
                ks.setdefault(pair, {})[f.test_year] = f"{f.k:g}" + (" (por defecto)" if f.k_fallback else "")
    years = sorted({y for d in ks.values() for y in d})
    L += md_table(
        ["Año de test"] + [DIRECTION[p] for p in MAIN_PAIRS],
        [[y] + [ks.get(p, {}).get(y, "-") for p in MAIN_PAIRS] for y in years],
    )
    L += [
        "",
        "`k` es un pseudo-conteo en unidades del origen: `k = 0` es el cociente puro del bloque y `k = 10000` "
        "casi lo lleva al factor nacional.",
        "",
    ]

    # --- Intervalos ---
    L += ["## Intervalos de la serie inversa", ""]
    L += [
        f"Nivel nominal {NOMINAL:.0%}. Cobertura empírica sobre bloque-mes con actividad (conteo de origen u "
        "observado mayor que cero), por año de test (año afuera). Anchura relativa = suma de anchuras / suma de "
        "predicciones.",
        "",
        "- `jackknife (factor)`: factor +/- z * error estándar jackknife de los factores con un año afuera "
        "(z = 1,28). Solo refleja la incertidumbre del factor, no el ruido del conteo del mes de test.",
        "- `dispersion interanual`: cuantiles 10 % y 90 % de los factores de cada año de entrenamiento por "
        "separado (sin encogimiento), aplicados al conteo de origen. Incluye la variación año a año del cociente.",
        "",
    ]
    cc = cov[(cov["pair"] == "modis_to_viirs") & (cov["scheme"] == "loyo")]
    years = sorted({int(y) for y in cc["test_year"] if str(y) != "all"})
    rows = []
    for y in years + ["all"]:
        cells = ["todos" if y == "all" else y]
        for name in INTERVALS:
            r = cc[(cc["interval"] == name) & (cc["test_year"].astype(str) == str(y))].iloc[0]
            cells += [pct(r["coverage"]), num(r["rel_width"], 2)]
        rows.append(cells)
    L += md_table(
        ["Año"] + [f"{INTERVALS[n]} {h}" for n in INTERVALS for h in ("cobertura", "anchura")], rows
    )
    L.append("")

    # --- Variantes ---
    L += ["## Variantes: Terra solo y NOAA-20 -> S-NPP (año afuera)", ""]
    rows = []
    for pair in ("viirs_to_terra", "terra_to_viirs", "noaa20_to_snpp"):
        for method, mname in METHODS.items():
            a = _row(scores, pair, "loyo", method, "all", "block-month")
            b = _row(scores, pair, "loyo", method, "all", "block-year")
            if a is None:
                continue
            rows.append([PAIRS[pair].label, mname, pct(a["bias"], True), pct(a["wape"]), pct(b["wape"])])
    L += md_table(["Par", "Método", "Sesgo b-mes", "WAPE b-mes", "WAPE b-año"], rows)
    L.append("")

    # --- Estabilidad ---
    L += ["## Estabilidad", ""]
    L += [
        "Cocientes de sumas nacionales por año con el conteo por defecto (grilla de 0,1°). `Meses` = meses "
        "completos usados (los parciales están excluidos). Sin ajuste por época: es la tabla pedida por el diseño "
        "para decidir si hace falta. La tabla por bloque no se incluye en esta corrida.",
        "",
        "### MODIS / S-NPP por año",
        "",
    ]
    rows = [
        [
            int(r["year"]),
            int(r["months"]),
            num(r["ratio"]),
            num(r["ratio_day"]),
            num(r["ratio_night"]),
            num(r["terra_snpp"]),
            num(r["aqua_snpp"]),
        ]
        for _, r in mod.iterrows()
    ]
    L += md_table(["Año", "Meses", "MODIS/S-NPP", "Día", "Noche", "Terra/S-NPP", "Aqua/S-NPP"], rows)
    L += ["", "### NOAA-20 / S-NPP por año (control sin MODIS)", ""]
    n20 = inp.grid_tables["noaa20_snpp"]
    L += md_table(
        ["Año", "Meses", "NOAA-20/S-NPP", "Día", "Noche"],
        [
            [
                int(r["year"]),
                int(r["months"]),
                num(r["ratio"], 4),
                num(r["ratio_day"], 4),
                num(r["ratio_night"], 4),
            ]
            for _, r in n20.iterrows()
        ],
    )
    L += ["", "### Terra / Aqua por año", ""]
    ta = inp.grid_tables["terra_aqua"]
    L += md_table(
        ["Año", "Meses", "Terra/Aqua", "Día", "Noche"],
        [
            [int(r["year"]), int(r["months"]), num(r["ratio"]), num(r["ratio_day"]), num(r["ratio_night"])]
            for _, r in ta.iterrows()
        ],
    )
    L += ["", "### Hora media de adquisición (UTC) por satélite y año", ""]
    L += [
        "Detecciones tras el filtro por defecto, desde `acq_datetime`. Las horas de noche posteriores a las "
        "12:00 se promedian como horas negativas para no cortar en la medianoche.",
        "",
    ]
    hrs = inp.det_tables["hours"]
    cols = [(s, dn) for s in ("terra", "aqua", "snpp", "noaa20") for dn in ("D", "N")]
    piv = hrs.pivot_table(index="year", columns=["satellite", "daynight"], values="hour")
    rows = []
    for y in piv.index:
        rows.append([int(y)] + [hhmm(piv.loc[y, c]) if c in piv.columns else "-" for c in cols])
    L += md_table(["Año"] + [f"{s} {dn}" for s, dn in cols], rows)
    L += ["", "### Con y sin filtro de `type`", ""]
    L += [
        "Cociente MODIS/S-NPP desde las detecciones, con el filtro por defecto (`type` = 0) y sin filtro de `type` "
        "(`types=(0,1,2,3)`, con `type` faltante incluido; mismos filtros de confianza). El mes parcial 2012-01 "
        "está fuera. Fracción con `type` distinto de 0 = 1 - conteo con filtro / conteo sin filtro.",
        "",
    ]
    rows = []
    for _, r in types.iterrows():
        rows.append(
            [
                int(r["year"]),
                int(r["modis_def"]),
                int(r["modis_all"]),
                pct(r["modis_type_share"]),
                num(r["ratio_def"]),
                num(r["ratio_all"]),
                pct(r["snpp_type_share"]),
            ]
        )
    L += md_table(
        [
            "Año",
            "MODIS con filtro",
            "MODIS sin filtro",
            "MODIS type != 0",
            "MODIS/S-NPP con filtro",
            "MODIS/S-NPP sin filtro",
            "S-NPP type != 0",
        ],
        rows,
    )
    L.append("")

    L += ["## Notas", ""]
    L += [
        "- Qué causa cada diferencia entre años (versión de MODIS, tipo de fuente, deriva orbital) está "
        "**sin verificar**: las tablas solo describen.",
        "- La serie inversa estima cuántos focos habría registrado VIIRS en un bloque y mes; no ubica focos "
        "individuales. Se llama 'estimado', nunca 'detectado'.",
        "- No hay ajuste por época: si la tabla de estabilidad muestra un escalón con el control NOAA-20/S-NPP "
        "plano, el diseño pide ajustar por época y retomar SA2.8.",
    ]
    return "\n".join(L) + "\n"
